int delete_if_exists(const char *filepath) {
    int fd = open(filepath, O_RDONLY | O_NOFOLLOW);
    if (fd < 0) return 0;
    struct stat st;
    if (fstat(fd, &st) == 0 && S_ISREG(st.st_mode)) {
        close(fd);
        unlink(filepath);
        return 1;
    }
    close(fd);
    /* retry on transient error */
    return 0;
}

